-- ---------- 1. JWT accessors -------------------------------------
-- Transaction-local GUCs, set once per request from a VERIFIED token.
-- Policies call these; they never read current_setting() directly.
CREATE SCHEMA IF NOT EXISTS app;

CREATE OR REPLACE FUNCTION app.jwt_email() RETURNS text
  LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.jwt_email', true), '')
  $$;

CREATE OR REPLACE FUNCTION app.jwt_principal() RETURNS text
  LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.jwt_principal', true), '')
  $$;

CREATE OR REPLACE FUNCTION app.jwt_organization() RETURNS text
  LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.jwt_organization', true), '')
  $$;

CREATE OR REPLACE FUNCTION app.jwt_role() RETURNS text
  LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.jwt_role', true), '')
  $$;

CREATE OR REPLACE FUNCTION app.jwt_user() RETURNS text
  LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.jwt_user', true), '')
  $$;

CREATE OR REPLACE FUNCTION app.jwt_agent() RETURNS text
  LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.jwt_agent', true), '')
  $$;

CREATE OR REPLACE FUNCTION app.jwt_is_admin() RETURNS boolean
  LANGUAGE sql STABLE AS $$
    SELECT coalesce(current_setting('app.jwt_is_admin', true) = 'true', false)
  $$;

-- ---------- 2. SECURITY DEFINER pass ------------------------------
-- Calc/lookup/aggregation functions are pure derivations over the whole
-- dataset. A policy predicate calls them, so they must see all rows --
-- otherwise they return NULL for a non-superuser and every policy
-- silently denies everything (verified against this database).
-- The CUT belongs at the policy and view layer above, never inside the
-- DAG evaluator.
--
-- Safety: these take a primary key and return a scalar. A calc function
-- that took arbitrary input and returned rows would be a leak; do not
-- write one.
DO $$
DECLARE r record; n int := 0;
BEGIN
  FOR r IN
    SELECT p.oid::regprocedure AS sig
    FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
    WHERE ns.nspname = 'public'
      AND (p.proname LIKE 'calc\_%' OR p.proname LIKE 'get\_%')
      AND p.prokind = 'f'
  LOOP
    EXECUTE format('ALTER FUNCTION %s SECURITY DEFINER', r.sig);
    EXECUTE format('ALTER FUNCTION %s SET row_security = off', r.sig);
    EXECUTE format('ALTER FUNCTION %s SET search_path = public', r.sig);
    n := n + 1;
  END LOOP;
  RAISE NOTICE 'access-control: % derivation functions marked SECURITY DEFINER', n;
END $$;

